+    if (item.type === 'event') return asDate(item.startAt);
+    return asDate(item.dueAt || item.remindAt || item.createdAt);
+}
+
+function itemEndDate(item) {
+    if (!item) return null;
+    if (item.type === 'event') return asDate(item.endAt || item.startAt);
+    return itemDate(item);
+}
+
+function isSameLocalDay(value, dateKey) {
+    return localDateKey(value) === dateKey;
+}
+
+function topByDuration(sessions, getKey, now) {
+    const totals = new Map();
+    sessions.forEach((session) => {
+        const key = String(getKey(session) || '').trim();
+        if (!key) return;
+        totals.set(key, (totals.get(key) || 0) + getLiveSessionDurations(session, now).activeDurationMs);
+    });
+    return [...totals.entries()]
+        .sort((left, right) => right[1] - left[1] || left[0].localeCompare(right[0]))[0]?.[0] || '';
+}
+
+function nextThreatLabel(items, now) {
+    const nowTime = now instanceof Date ? now.getTime() : Date.now();
+    const next = (Array.isArray(items) ? items : [])
+        .filter((item) => {
+            const date = itemDate(item);
+            if (!date) return false;
+            if (item.type === 'deadline' && item.completed) return false;
+            const end = itemEndDate(item) || date;
+            return end.getTime() >= nowTime;
+        })
+        .sort((left, right) => itemDate(left).getTime() - itemDate(right).getTime())[0];
+    if (!next) return 'No upcoming local items';
+    const date = itemDate(next);
+    const time = date ? date.toLocaleString([], { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }) : 'unscheduled';
+    return `${next.title || 'Untitled item'} ${time}`;
+}
+
+export function getDaySummary({
+    sessions = [],
+    calendarItems = [],
+    proofTimestamps = [],
+    now = new Date(),
+    date,
+} = {}) {
+    const summaryDate = date || localDateKey(now);
+    const start = new Date(`${summaryDate}T00:00:00`);
+    const end = new Date(start.getTime() + DAY_MS);
+    const sessionList = Array.isArray(sessions) ? sessions : [];
+    const itemList = Array.isArray(calendarItems) ? calendarItems : [];
+    const proofList = Array.isArray(proofTimestamps) ? proofTimestamps : [];
+    const sessionsToday = sessionList.filter((session) => {
+        const started = asDate(session.startedAt);
+        return started && started.getTime() >= start.getTime() && started.getTime() < end.getTime();
+    });
+    const proofEventsToday = proofList.filter((event) => isSameLocalDay(event.createdAt, summaryDate));
+    const calendarToday = itemList.filter((item) => isSameLocalDay(itemDate(item), summaryDate));
+    const deadlines = calendarToday.filter((item) => item.type === 'deadline');
+    const overdueDeadlines = deadlines.filter((item) => {
+        if (item.completed) return false;
+        const due = itemDate(item);
+        return due && due.getTime() < (now instanceof Date ? now.getTime() : Date.now());
+    });
+    const totals = sessionsToday.reduce((acc, session) => {
+        const durations = getLiveSessionDurations(session, now);
+        acc.totalSessionMs += durations.durationMs;
+        acc.activeMs += durations.activeDurationMs;
+        acc.idleMs += durations.idleDurationMs;
+        acc.longestSessionMs = Math.max(acc.longestSessionMs, durations.durationMs);
+        return acc;
+    }, {
+        totalSessionMs: 0,
+        activeMs: 0,
+        idleMs: 0,
+        longestSessionMs: 0,
+    });
+
+    return {
+        date: summaryDate,
+        timezone: timezoneLabel(),
+        totalSessionMs: totals.totalSessionMs,
+        activeMs: totals.activeMs,
+        idleMs: totals.idleMs,
+        sessionCount: sessionsToday.length,
+        longestSessionMs: totals.longestSessionMs,
+        topProject: topByDuration(sessionsToday, (session) => session.projectName || session.projectId, now),
+        topMode: topByDuration(sessionsToday, (session) => session.mode, now),
+        eventsToday: calendarToday.filter((item) => item.type === 'event').length,
+        deadlinesDue: deadlines.length,
+        deadlinesCompleted: deadlines.filter((item) => item.completed).length,
+        overdueDeadlines: overdueDeadlines.length,
+        proofEventCount: proofEventsToday.length,
+        linkedCalendarItems: new Set(proofEventsToday.map((event) => event.calendarItemId).filter(Boolean)).size,
+        nextThreat: nextThreatLabel(itemList, now),
