/** Current localStorage keys for the NeuralShell hardware customization console. */
export const HARDWARE_CUSTOMIZATION_PROFILE_STORAGE_KEY = 'hardware_customization_profiles_v1';
export const HARDWARE_CUSTOMIZATION_SETTINGS_STORAGE_KEY = 'hardware_customization_settings_v1';

/** Legacy keys from pre-rename builds — read-only compatibility; do not write new data here. */
export const LEGACY_LUXGRID_PROFILE_STORAGE_KEY = 'luxgrid_profiles_v1';
export const LEGACY_LUXGRID_SETTINGS_STORAGE_KEY = 'luxgrid_settings_v1';

export const SELECTION_MODES = ['single', 'multi', 'row', 'zone'];
export const EFFECTS = [
    'Static',
    'Pulse',
    'Breathing',
    'Temperature Gradient',
    'Usage Meter',
    'Timer Fade',
];

export function nowIso() {
    return new Date().toISOString();
}

export function createDefaultZones() {
    return [
        {
            id: 'zone-main',
            name: 'Main Cluster',
            keyIds: ['K1', 'K2', 'K3', 'K4', 'K5', 'K6'],
            color: '#22d3ee',
            effect: 'Static',
            brightness: 80,
            speed: 40,
            sensorSource: 'none',
        },
        {
            id: 'zone-nav',
            name: 'Navigation',
            keyIds: ['K7', 'K8', 'K9', 'K10'],
            color: '#a78bfa',
            effect: 'Pulse',
            brightness: 70,
            speed: 35,
            sensorSource: 'cpu',
        },
    ];
}

export function createDefaultProfile(name = 'Thermal HUD') {
    const ts = nowIso();
    return {
        id: `profile-${Math.random().toString(36).slice(2, 9)}`,
        name,
        description: 'Default hardware customization profile.',
        zones: createDefaultZones(),
        effects: { global: 'Static' },
        createdAt: ts,
        updatedAt: ts,
        lastAppliedAt: '',
    };
}

export function defaultProfiles() {
    return [
        createDefaultProfile('Thermal HUD'),
        createDefaultProfile('Sleep Ritual'),
    ];
}

export function defaultSettings() {
    return {
        general: {
            startInSimulatorMode: true,
            startMinimized: false,
            minimizeToTray: false,
            confirmBeforeExit: true,
            themeIntensity: 70,
            animationLevel: 'medium',
        },
        device: {
            autoScanOnLaunch: false,
            openRgbHost: '127.0.0.1',
            openRgbPort: 6742,
            hidScanEnabled: true,
            vendorLockWarnings: true,
        },
        profiles: {
            autoApplyLastProfile: false,
            saveProfileOnChange: true,
            defaultProfileId: '',
            backupProfiles: true,
        },
        proof: {
            saveProofLogs: true,
            includeSimulatorProofs: true,
            proofOutputFolder: 'proof/hardware-customization',
            timestampFormat: 'utc_iso',
        },
    };
}

export function keyboardLayout() {
    const rows = [
        ['K1', 'K2', 'K3', 'K4', 'K5', 'K6'],
        ['K7', 'K8', 'K9', 'K10', 'K11', 'K12'],
        ['K13', 'K14', 'K15', 'K16', 'K17', 'K18'],
        ['K19', 'K20', 'K21', 'K22', 'K23', 'K24'],
    ];
    return rows.map((row, rowIndex) => row.map((id, colIndex) => ({ id, rowIndex, colIndex })));
}

export function normalizeProfile(raw) {
    const ts = nowIso();
    return {
        id: String(raw && raw.id ? raw.id : `profile-${Math.random().toString(36).slice(2, 9)}`),
        name: String(raw && raw.name ? raw.name : 'Imported Profile'),
        description: String(raw && raw.description ? raw.description : ''),
        zones: Array.isArray(raw && raw.zones) ? raw.zones : [],
        effects: raw && typeof raw.effects === 'object' ? raw.effects : {},
        createdAt: String(raw && raw.createdAt ? raw.createdAt : ts),
        updatedAt: String(raw && raw.updatedAt ? raw.updatedAt : ts),
        lastAppliedAt: String(raw && raw.lastAppliedAt ? raw.lastAppliedAt : ''),
    };
}

const test = require('node:test');
const assert = require('node:assert/strict');

async function loadModel() {
  return import('../src/renderer/src/lib/hardwareCustomizationModel.js');
}

test('default profiles include zone/effect data', async () => {
  const model = await loadModel();
  const profiles = model.defaultProfiles();
  assert.ok(Array.isArray(profiles));
  assert.ok(profiles.length >= 2);
  assert.ok(Array.isArray(profiles[0].zones));
  assert.equal(typeof profiles[0].effects, 'object');
});

test('default settings include required sections', async () => {
  const model = await loadModel();
  const settings = model.defaultSettings();
  assert.ok(settings.general);
  assert.ok(settings.device);
  assert.ok(settings.profiles);
  assert.ok(settings.proof);
});

test('selection modes and effects contain MVP values', async () => {
  const model = await loadModel();
  assert.ok(model.SELECTION_MODES.includes('single'));
  assert.ok(model.SELECTION_MODES.includes('multi'));
  assert.ok(model.EFFECTS.includes('Temperature Gradient'));
  assert.ok(model.EFFECTS.includes('Timer Fade'));
});

test('normalize profile preserves imported shape', async () => {
  const model = await loadModel();
  const normalized = model.normalizeProfile({
    name: 'Imported',
    zones: [{ id: 'z1', keyIds: ['K1'] }],
    effects: { global: 'Static' },
  });
  assert.equal(normalized.name, 'Imported');
  assert.ok(Array.isArray(normalized.zones));
  assert.equal(normalized.effects.global, 'Static');
  assert.ok(normalized.id.startsWith('profile-'));
});

import React from 'react';
import {
    HARDWARE_CUSTOMIZATION_PROFILE_STORAGE_KEY,
    HARDWARE_CUSTOMIZATION_SETTINGS_STORAGE_KEY,
    LEGACY_LUXGRID_PROFILE_STORAGE_KEY,
    LEGACY_LUXGRID_SETTINGS_STORAGE_KEY,
    SELECTION_MODES,
    EFFECTS,
    defaultProfiles,
    defaultSettings,
    keyboardLayout,
    normalizeProfile,
    nowIso,
} from '../lib/hardwareCustomizationModel.js';

function readStorage(key, fallback) {
    if (typeof window === 'undefined' || !window.localStorage) return fallback;
    try {
        const parsed = JSON.parse(window.localStorage.getItem(key) || 'null');
        return parsed == null ? fallback : parsed;
    } catch {
        return fallback;
    }
}

function writeStorage(key, value) {
    if (typeof window === 'undefined' || !window.localStorage) return;
    window.localStorage.setItem(key, JSON.stringify(value));
}

function readStorageWithLegacyMigration(primaryKey, legacyKey, fallback) {
    const primary = readStorage(primaryKey, null);
    if (primary != null) return primary;
    const legacy = readStorage(legacyKey, null);
    if (legacy != null) {
        writeStorage(primaryKey, legacy);
        return legacy;
    }
    return fallback;
}

function downloadJson(filename, payload) {
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = filename;
    anchor.click();
    URL.revokeObjectURL(url);
}

function deriveKeyColor(keyId, profile) {
    const zones = Array.isArray(profile && profile.zones) ? profile.zones : [];
    for (const zone of zones) {
        if (Array.isArray(zone.keyIds) && zone.keyIds.includes(keyId)) {
            return zone.color || '#1f2937';
        }
    }
    return '#111827';
}

function profileById(profiles, id) {
    return profiles.find((item) => String(item.id) === String(id)) || null;
}

async function scanDevices(settings) {
    const devices = [
        {
            id: 'sim-keyboard',
            name: 'Simulated Keyboard',
            vendor: 'NeuralShell',
            product: 'Hardware Simulator',
            type: 'keyboard',
            mode: 'simulator',
            writable: true,
            reason: 'Simulator device available.',
            capabilities: ['zones', 'effects', 'proof'],
        },
    ];
    if (window.api && window.api.rgb && typeof window.api.rgb.status === 'function') {
        const rgb = await window.api.rgb.status().catch(() => null);
        const connected = Boolean(rgb && rgb.transport && rgb.transport.connected);
        if (connected) {
            devices.push({
                id: 'openrgb-bridge',
                name: 'OpenRGB Bridge',
                vendor: 'OpenRGB',
                product: 'OpenRGB Server',
                type: 'bridge',
                mode: 'openrgb',
                writable: false,
                reason: 'OpenRGB connected; hardware write adapter not implemented.',
                capabilities: ['status'],
            });
        } else {
            devices.push({
                id: 'openrgb-bridge',
                name: 'OpenRGB Bridge',
                vendor: 'OpenRGB',
                product: 'OpenRGB Server',
                type: 'bridge',
                mode: 'openrgb',
                writable: false,
                reason: 'OpenRGB server not connected.',
                capabilities: [],
            });
        }
    }
    if (settings.device.hidScanEnabled && typeof navigator !== 'undefined' && 'hid' in navigator) {
        devices.push({
            id: 'hid-local',
            name: 'Local HID Interface',
            vendor: 'OS',
            product: 'HID',
            type: 'keyboard',
            mode: 'hid',
            writable: false,
            reason: 'HID device found, no writable RGB endpoint detected.',
            capabilities: ['enumeration'],
        });
    }
    devices.push({
        id: 'vendor-lock',
        name: 'Roccat Bridge',
        vendor: 'Roccat',
        product: 'Swarm Managed Device',
        type: 'keyboard',
        mode: 'vendor',
        writable: false,
        reason: 'Device may be locked by vendor software. Close Roccat Swarm before Live Mode.',
        capabilities: ['vendor_lock_warning'],
    });
    return devices;
}

export default function HardwareCustomizationConsole({ open, onClose, onOpenSettings }) {
    const [profiles, setProfiles] = React.useState(() =>
        readStorageWithLegacyMigration(
            HARDWARE_CUSTOMIZATION_PROFILE_STORAGE_KEY,
            LEGACY_LUXGRID_PROFILE_STORAGE_KEY,
            defaultProfiles(),
        ),
    );
    const [settings, setSettings] = React.useState(() =>
        readStorageWithLegacyMigration(
            HARDWARE_CUSTOMIZATION_SETTINGS_STORAGE_KEY,
            LEGACY_LUXGRID_SETTINGS_STORAGE_KEY,
            defaultSettings(),
        ),
    );
    const [activeProfileId, setActiveProfileId] = React.useState(() => {
        const seed = readStorageWithLegacyMigration(
            HARDWARE_CUSTOMIZATION_PROFILE_STORAGE_KEY,
            LEGACY_LUXGRID_PROFILE_STORAGE_KEY,
            defaultProfiles(),
        );
        return seed[0] ? seed[0].id : '';
    });
    const [previewProfileId, setPreviewProfileId] = React.useState(() => activeProfileId);
    const [lastAppliedProfileId, setLastAppliedProfileId] = React.useState('');
    const [lastAppliedAt, setLastAppliedAt] = React.useState('');
    const [lastApplyMode, setLastApplyMode] = React.useState('simulator');
    const [lastApplyStatus, setLastApplyStatus] = React.useState('No profile applied yet.');
    const [selectedDeviceId, setSelectedDeviceId] = React.useState('sim-keyboard');
    const [selectionMode, setSelectionMode] = React.useState('single');
    const [selectedKeyIds, setSelectedKeyIds] = React.useState([]);
    const [selectedZoneId, setSelectedZoneId] = React.useState('');
    const [devices, setDevices] = React.useState([]);
    const [proofOutput, setProofOutput] = React.useState(null);
    const [proofStatus, setProofStatus] = React.useState('');
    const [showSettingsModal, setShowSettingsModal] = React.useState(false);
    const [settingsTab, setSettingsTab] = React.useState('general');
    const [statusText, setStatusText] = React.useState('Simulator device available.');
    const fileInputRef = React.useRef(null);

    React.useEffect(() => writeStorage(HARDWARE_CUSTOMIZATION_PROFILE_STORAGE_KEY, profiles), [profiles]);
    React.useEffect(() => writeStorage(HARDWARE_CUSTOMIZATION_SETTINGS_STORAGE_KEY, settings), [settings]);
    React.useEffect(() => {
        if (!open) return;
        if (!settings.device.autoScanOnLaunch) return;
        void scanDevices(settings).then((list) => setDevices(list));
    }, [open, settings]);

    const profile = React.useMemo(() => profileById(profiles, previewProfileId) || profiles[0] || null, [profiles, previewProfileId]);
    const activeProfile = React.useMemo(() => profileById(profiles, activeProfileId) || profiles[0] || null, [profiles, activeProfileId]);
    const device = React.useMemo(() => devices.find((item) => item.id === selectedDeviceId) || null, [devices, selectedDeviceId]);
    const layout = React.useMemo(() => keyboardLayout(), []);

    React.useEffect(() => {
        if (!previewProfileId && profiles[0]) setPreviewProfileId(profiles[0].id);
        if (!activeProfileId && profiles[0]) setActiveProfileId(profiles[0].id);
    }, [profiles, previewProfileId, activeProfileId]);

    if (!open) return null;

    const updateProfile = (next) => {
        setProfiles((prev) => prev.map((item) => (item.id === next.id ? next : item)));
    };

    const applySimulator = () => {
        if (!profile) return;
        const ts = nowIso();
        setActiveProfileId(profile.id);
        setPreviewProfileId(profile.id);
        setLastAppliedProfileId(profile.id);
        setLastAppliedAt(ts);
        setLastApplyMode('simulator');
        setLastApplyStatus(`Applied ${profile.name} to simulator.`);
        setStatusText(`Applied ${profile.name} to simulator.`);
        updateProfile({ ...profile, updatedAt: ts, lastAppliedAt: ts });
    };

    const applyDevice = () => {
        if (!device || !device.writable) {
            const reason = device ? device.reason : 'Cannot apply to device: no writable device selected.';
            setLastApplyMode('failed');
            setLastApplyStatus(reason || 'Cannot apply to device: no writable device selected.');
            setStatusText(reason || 'Cannot apply to device: no writable device selected.');
            return;
        }
        const ts = nowIso();
        setLastAppliedAt(ts);
        setLastAppliedProfileId(profile ? profile.id : '');
        setLastApplyMode(device.mode);
        setLastApplyStatus(`Applied ${profile ? profile.name : 'profile'} to ${device.name}.`);
    };

    const createProfile = () => {
        const ts = nowIso();
        const next = normalizeProfile({
            name: `New Profile ${profiles.length + 1}`,
            description: '',
            zones: [],
            effects: { global: 'Static' },
            createdAt: ts,
            updatedAt: ts,
        });
        setProfiles((prev) => [...prev, next]);
        setPreviewProfileId(next.id);
        setActiveProfileId(next.id);
    };

    const duplicateProfile = () => {
        if (!profile) return;
        const ts = nowIso();
        const copy = normalizeProfile({
            ...profile,
            id: `profile-${Math.random().toString(36).slice(2, 9)}`,
            name: `${profile.name} Copy`,
            zones: JSON.parse(JSON.stringify(profile.zones || [])),
            effects: JSON.parse(JSON.stringify(profile.effects || {})),
            createdAt: ts,
            updatedAt: ts,
            lastAppliedAt: '',
        });
        setProfiles((prev) => [...prev, copy]);
        setPreviewProfileId(copy.id);
    };

    const deleteProfile = () => {
        if (!profile) return;
        if (profiles.length <= 1) {
            setStatusText('Cannot delete the last profile.');
            return;
        }
        const ok = window.confirm(`Delete profile "${profile.name}"?`);
        if (!ok) return;
        const next = profiles.filter((item) => item.id !== profile.id);
        setProfiles(next);
        setPreviewProfileId(next[0].id);
        if (activeProfileId === profile.id) setActiveProfileId(next[0].id);
    };

    const resetProfile = () => {
        if (!profile) return;
        const ts = nowIso();
        const reset = { ...profile, zones: [], effects: { global: 'Static' }, updatedAt: ts };
        updateProfile(reset);
        setStatusText(`Reset ${profile.name}.`);
    };

    const exportProfile = () => {
        if (!profile) return;
        downloadJson(`${profile.name.replace(/\s+/g, '_').toLowerCase()}_hardware_profile.json`, profile);
    };

    const importProfile = async (event) => {
        const file = event.target.files && event.target.files[0];
        if (!file) return;
        try {
            const text = await file.text();
            const parsed = JSON.parse(text);
            if (!parsed || typeof parsed !== 'object' || !parsed.name) {
                throw new Error('Bad profile import: missing name.');
            }
            const imported = normalizeProfile(parsed);
            setProfiles((prev) => [...prev, imported]);
            setPreviewProfileId(imported.id);
            setStatusText(`Imported profile "${imported.name}".`);
        } catch (error) {
            setStatusText(`Bad import: ${error && error.message ? error.message : 'Invalid JSON'}`);
        } finally {
            if (fileInputRef.current) fileInputRef.current.value = '';
        }
    };

    const toggleKey = (key) => {
        const keyId = key.id;
        if (selectionMode === 'single') {
            setSelectedKeyIds([keyId]);
            return;
        }
        if (selectionMode === 'row') {
            const rowIds = layout[key.rowIndex].map((item) => item.id);
            setSelectedKeyIds(rowIds);
            return;
        }
        if (selectionMode === 'zone' && profile) {
            const zone = (profile.zones || []).find((item) => item.id === selectedZoneId) || (profile.zones || [])[0];
            setSelectedKeyIds(zone ? zone.keyIds || [] : []);
            return;
        }
        setSelectedKeyIds((prev) => prev.includes(keyId) ? prev.filter((id) => id !== keyId) : [...prev, keyId]);
    };

    const assignSelectionToZone = () => {
        if (!profile || !selectedZoneId) return;
        const zones = (profile.zones || []).map((zone) => {
            if (zone.id === selectedZoneId) {
                return { ...zone, keyIds: Array.from(new Set(selectedKeyIds)) };
            }
            return { ...zone, keyIds: (zone.keyIds || []).filter((id) => !selectedKeyIds.includes(id)) };
        });
        updateProfile({ ...profile, zones, updatedAt: nowIso() });
    };

    const createZone = () => {
        if (!profile) return;
        const zone = {
            id: `zone-${Math.random().toString(36).slice(2, 8)}`,
            name: `Zone ${((profile.zones || []).length + 1)}`,
            keyIds: [],
            color: '#22d3ee',
            effect: 'Static',
            brightness: 80,
            speed: 40,
            sensorSource: 'none',
        };
        updateProfile({ ...profile, zones: [...(profile.zones || []), zone], updatedAt: nowIso() });
        setSelectedZoneId(zone.id);
    };

    const updateZone = (zoneId, patch) => {
        if (!profile) return;
        const zones = (profile.zones || []).map((zone) => zone.id === zoneId ? { ...zone, ...patch } : zone);
        updateProfile({ ...profile, zones, updatedAt: nowIso() });
    };

    const deleteZone = () => {
        if (!profile || !selectedZoneId) return;
        const zones = (profile.zones || []).filter((zone) => zone.id !== selectedZoneId);
        updateProfile({ ...profile, zones, updatedAt: nowIso() });
        setSelectedZoneId(zones[0] ? zones[0].id : '');
    };

    const runScan = async () => {
        const list = await scanDevices(settings);
        setDevices(list);
        if (!selectedDeviceId && list[0]) setSelectedDeviceId(list[0].id);
        setStatusText(list[0] ? list[0].reason : 'No devices detected.');
    };

    const runProof = () => {
        if (!profile) return;
        if (!device || !device.writable) {
            const failure = {
                timestamp: nowIso(),
                success: false,
                reason: device && device.reason ? device.reason : 'No writable device selected',
            };
            setProofOutput(failure);
            setProofStatus('proof-failed');
            return;
        }
        const zones = Array.isArray(profile.zones) ? profile.zones : [];
        const keysApplied = zones.reduce((sum, zone) => sum + (Array.isArray(zone.keyIds) ? zone.keyIds.length : 0), 0);
        const success = {
            timestamp: nowIso(),
            mode: 'simulator',
            deviceId: 'sim-keyboard',
            deviceName: 'Simulated Keyboard',
            profile: profile.name,
            zonesApplied: zones.length,
            keysApplied,
            success: true,
            notes: ['Simulator proof only — no physical device changed.'],
        };
        setProofOutput(success);
        setProofStatus('proof-success');
    };

    const canDeviceApply = Boolean(device && device.writable);
    const selectedZone = (profile && (profile.zones || []).find((zone) => zone.id === selectedZoneId)) || null;
    const allKeys = layout.flat();

    return (
        <>
            <div className="fixed inset-0 z-[146] bg-black/60" onClick={onClose} />
            <section data-testid="hardware-appliance-manager" className="fixed inset-x-8 top-16 bottom-6 z-[147] rounded-2xl border border-cyan-300/25 bg-slate-950 shadow-[0_20px_90px_rgba(0,0,0,0.75)] overflow-hidden flex flex-col">
                <div className="px-4 py-3 border-b border-white/10 bg-black/30 flex items-center justify-between gap-3">
                    <div>
                        <div className="text-[10px] uppercase tracking-[0.16em] text-cyan-300 font-bold">Hardware Customization Console</div>
                        <div className="text-[10px] font-mono text-slate-500">NeuralShell can detect supported local devices exposed through Simulator, OpenRGB, HID, or future vendor adapters.</div>
                    </div>
                    <button type="button" onClick={onClose} className="h-8 w-8 rounded-full border border-white/10 text-slate-300 hover:bg-white/10">✕</button>
                </div>

                <div className="grid grid-cols-4 gap-3 p-3 overflow-auto flex-1 min-h-0">
                    <section className="col-span-1 rounded-xl border border-white/10 bg-black/20 p-3 space-y-2">
                        <div data-testid="active-profile-card" className="text-[10px] font-mono text-cyan-100">
                            Active: {activeProfile ? activeProfile.name : 'n/a'}
                        </div>
                        <div className="space-y-1 max-h-44 overflow-auto">
                            {profiles.map((item) => (
                                <button key={item.id} type="button" onClick={() => setPreviewProfileId(item.id)} className={`w-full text-left px-2 py-1 rounded border text-[10px] font-mono ${item.id === previewProfileId ? 'border-cyan-300/40 bg-cyan-500/10 text-cyan-100' : 'border-white/10 bg-black/30 text-slate-300'}`}>
                                    {item.name}
                                </button>
                            ))}
                        </div>
                        <input data-testid="profile-name-input" value={profile ? profile.name : ''} onChange={(e) => profile && updateProfile({ ...profile, name: e.target.value, updatedAt: nowIso() })} className="w-full rounded border border-white/10 bg-black/30 px-2 py-1 text-[10px] text-slate-200" />
                        <textarea data-testid="profile-description-input" value={profile ? profile.description : ''} onChange={(e) => profile && updateProfile({ ...profile, description: e.target.value, updatedAt: nowIso() })} className="w-full rounded border border-white/10 bg-black/30 px-2 py-1 text-[10px] text-slate-200" />
                        <div className="grid grid-cols-2 gap-1">
                            <button data-testid="profile-create-button" type="button" onClick={createProfile} className="px-2 py-1 rounded border border-white/10 text-[9px]">New</button>
                            <button data-testid="profile-duplicate-button" type="button" onClick={duplicateProfile} className="px-2 py-1 rounded border border-white/10 text-[9px]">Duplicate</button>
                            <button data-testid="profile-rename-button" type="button" onClick={() => profile && setStatusText(`Renamed profile to ${profile.name}.`)} className="px-2 py-1 rounded border border-white/10 text-[9px]">Rename</button>
                            <button data-testid="profile-delete-button" type="button" onClick={deleteProfile} className="px-2 py-1 rounded border border-white/10 text-[9px]">Delete</button>
                            <button data-testid="profile-export-button" type="button" onClick={exportProfile} className="px-2 py-1 rounded border border-white/10 text-[9px]">Export</button>
                            <button data-testid="profile-import-button" type="button" onClick={() => fileInputRef.current && fileInputRef.current.click()} className="px-2 py-1 rounded border border-white/10 text-[9px]">Import</button>
                            <button data-testid="profile-reset-button" type="button" onClick={resetProfile} className="px-2 py-1 rounded border border-white/10 text-[9px]">Reset</button>
                        </div>
                        <input ref={fileInputRef} type="file" accept=".json,application/json" onChange={importProfile} className="hidden" />
                    </section>

                    <section className="col-span-2 rounded-xl border border-white/10 bg-black/20 p-3 space-y-2">
                        <div className="flex items-center justify-between gap-2">
                            <select data-testid="selection-mode-select" value={selectionMode} onChange={(e) => setSelectionMode(e.target.value)} className="rounded border border-white/10 bg-black/30 px-2 py-1 text-[10px]">
                                {SELECTION_MODES.map((mode) => <option key={mode} value={mode}>{mode}</option>)}
                            </select>
                            <span data-testid="selected-key-count" className="text-[10px] font-mono text-cyan-100">{selectedKeyIds.length} selected</span>
                            <button data-testid="selection-clear-button" type="button" onClick={() => setSelectedKeyIds([])} className="px-2 py-1 rounded border border-white/10 text-[9px]">Clear</button>
                            <button data-testid="selection-invert-button" type="button" onClick={() => setSelectedKeyIds(allKeys.map((key) => key.id).filter((id) => !selectedKeyIds.includes(id)))} className="px-2 py-1 rounded border border-white/10 text-[9px]">Invert</button>
                            <button data-testid="selection-all-button" type="button" onClick={() => setSelectedKeyIds(allKeys.map((key) => key.id))} className="px-2 py-1 rounded border border-white/10 text-[9px]">All</button>
                        </div>
                        <div className="space-y-1">
                            {layout.map((row) => (
                                <div key={row[0].id} className="flex gap-1">
                                    {row.map((key) => {
                                        const selected = selectedKeyIds.includes(key.id);
                                        return (
                                            <button
                                                key={key.id}
                                                type="button"
                                                data-testid={selected ? 'keyboard-key-selected' : 'keyboard-key'}
                                                onClick={() => toggleKey(key)}
                                                className={`h-8 w-12 rounded border text-[9px] font-mono ${selected ? 'border-cyan-300 bg-cyan-500/20 text-cyan-100' : 'border-white/10 text-slate-200'}`}
                                                style={{ backgroundColor: selected ? undefined : deriveKeyColor(key.id, profile) }}
                                            >
                                                {key.id}
                                            </button>
                                        );
                                    })}
                                </div>
                            ))}
                        </div>
                    </section>

                    <section className="col-span-1 rounded-xl border border-white/10 bg-black/20 p-3 space-y-2">
                        <button data-testid="zone-create-button" type="button" onClick={createZone} className="w-full px-2 py-1 rounded border border-white/10 text-[9px]">Create Zone</button>
                        <select value={selectedZoneId} onChange={(e) => setSelectedZoneId(e.target.value)} className="w-full rounded border border-white/10 bg-black/30 px-2 py-1 text-[10px]">
                            <option value="">Select Zone</option>
                            {(profile && profile.zones || []).map((zone) => <option key={zone.id} value={zone.id}>{zone.name}</option>)}
                        </select>
                        <input data-testid="zone-rename-input" value={selectedZone ? selectedZone.name : ''} onChange={(e) => selectedZone && updateZone(selectedZone.id, { name: e.target.value })} className="w-full rounded border border-white/10 bg-black/30 px-2 py-1 text-[10px]" />
                        <button data-testid="zone-delete-button" type="button" onClick={deleteZone} className="w-full px-2 py-1 rounded border border-white/10 text-[9px]">Delete Zone</button>
                        <input data-testid="zone-color-picker" type="color" value={selectedZone ? selectedZone.color : '#22d3ee'} onChange={(e) => selectedZone && updateZone(selectedZone.id, { color: e.target.value })} className="w-full h-8" />
                        <select data-testid="zone-effect-select" value={selectedZone ? selectedZone.effect : 'Static'} onChange={(e) => selectedZone && updateZone(selectedZone.id, { effect: e.target.value })} className="w-full rounded border border-white/10 bg-black/30 px-2 py-1 text-[10px]">
                            {EFFECTS.map((effect) => <option key={effect} value={effect}>{effect}</option>)}
                        </select>
                        <input data-testid="zone-brightness-slider" type="range" min="0" max="100" value={selectedZone ? selectedZone.brightness : 80} onChange={(e) => selectedZone && updateZone(selectedZone.id, { brightness: Number(e.target.value) })} />
                        <input data-testid="zone-speed-slider" type="range" min="0" max="100" value={selectedZone ? selectedZone.speed : 40} onChange={(e) => selectedZone && updateZone(selectedZone.id, { speed: Number(e.target.value) })} />
                        <select data-testid="zone-sensor-source-select" value={selectedZone ? selectedZone.sensorSource : 'none'} onChange={(e) => selectedZone && updateZone(selectedZone.id, { sensorSource: e.target.value })} className="w-full rounded border border-white/10 bg-black/30 px-2 py-1 text-[10px]">
                            <option value="none">none</option>
                            <option value="cpu">cpu</option>
                            <option value="gpu">gpu</option>
                            <option value="timer">timer</option>
                        </select>
                        <button data-testid="assign-selection-zone-button" type="button" onClick={assignSelectionToZone} className="w-full px-2 py-1 rounded border border-white/10 text-[9px]">Assign selection</button>
                        <button data-testid="zone-preview-button" type="button" onClick={() => setStatusText(selectedZone ? `Previewing ${selectedZone.name}` : 'Select a zone first.')} className="w-full px-2 py-1 rounded border border-white/10 text-[9px]">Preview Zone</button>
                        <div data-testid="zone-assigned-keys" className="text-[9px] font-mono text-slate-400">{selectedZone ? (selectedZone.keyIds || []).join(', ') || 'none' : 'none'}</div>
                    </section>
                </div>

                <div className="px-3 py-2 border-t border-white/10 bg-black/40 space-y-2">
                    <div className="flex flex-wrap items-center gap-2 text-[10px] font-mono">
                        <button data-testid="device-scan-button" type="button" onClick={runScan} className="px-2 py-1 rounded border border-white/10">Scan Devices</button>
                        <button data-testid="app-restart-scan-button" type="button" onClick={runScan} className="px-2 py-1 rounded border border-white/10">Restart Scan</button>
                        <button data-testid="apply-simulator-button" type="button" onClick={applySimulator} className="px-2 py-1 rounded border border-cyan-300/30 bg-cyan-500/10">Apply to Simulator</button>
                        <button data-testid="apply-device-button" type="button" disabled={!canDeviceApply} onClick={applyDevice} className="px-2 py-1 rounded border border-white/10 disabled:opacity-50">Apply to Device</button>
                        <span data-testid="profile-apply-status">{statusText}</span>
                    </div>

                    <div className="flex flex-wrap gap-2">
                        {devices.map((item) => (
                            <button key={item.id} type="button" data-testid="device-card" onClick={() => setSelectedDeviceId(item.id)} className={`px-2 py-1 rounded border text-[9px] font-mono ${item.id === selectedDeviceId ? 'border-cyan-300/40 bg-cyan-500/10' : 'border-white/10'}`}>
                                <div>{item.name}</div>
                                <div data-testid="device-mode-badge">{item.mode}</div>
                                <div data-testid="device-writable-status">{item.writable ? 'writable' : 'read-only'}</div>
                                <div data-testid="device-lock-reason">{item.reason}</div>
                            </button>
                        ))}
                    </div>

                    <div className="flex flex-wrap items-center gap-2 text-[10px] font-mono">
                        <span data-testid="last-applied-status">{lastApplyStatus}</span>
                        <span data-testid="last-applied-at">{lastAppliedAt || 'n/a'}</span>
                    </div>

                    <div className="flex items-center gap-2">
                        <button data-testid="proof-run-button" type="button" onClick={runProof} className="px-2 py-1 rounded border border-white/10">Run Proof</button>
                        <div data-testid="proof-mode" className="text-[10px] font-mono">{lastApplyMode}</div>
                        <div data-testid="proof-success" className="text-[10px] font-mono">{proofStatus}</div>
                    </div>
                    <pre data-testid="proof-output" className="max-h-32 overflow-auto text-[9px] font-mono border border-white/10 rounded p-2 bg-black/40">{proofOutput ? JSON.stringify(proofOutput, null, 2) : 'No proof yet.'}</pre>
                    <div data-testid="proof-reason" className="text-[10px] font-mono text-slate-400">{proofOutput && !proofOutput.success ? proofOutput.reason : ''}</div>

                    <div className="flex items-center gap-2">
                        <button data-testid="settings-button" type="button" onClick={() => setShowSettingsModal(true)} className="px-2 py-1 rounded border border-white/10">Settings</button>
                        <button data-testid="app-settings-button" type="button" onClick={() => setShowSettingsModal(true)} className="px-2 py-1 rounded border border-white/10">App Settings</button>
                        <button data-testid="app-minimize-button" type="button" disabled={!(window.api && window.api.app && typeof window.api.app.minimize === 'function')} onClick={() => window.api.app.minimize()} className="px-2 py-1 rounded border border-white/10 disabled:opacity-50">Minimize</button>
                        <button data-testid="app-exit-button" type="button" disabled={!(window.api && window.api.app && typeof window.api.app.exit === 'function')} onClick={() => window.api.app.exit()} className="px-2 py-1 rounded border border-white/10 disabled:opacity-50">Exit</button>
                        <button type="button" onClick={() => typeof onOpenSettings === 'function' && onOpenSettings()} className="px-2 py-1 rounded border border-white/10">Open App Settings</button>
                    </div>
                </div>
            </section>

            {showSettingsModal && (
                <>
                    <div className="fixed inset-0 z-[148] bg-black/50" onClick={() => setShowSettingsModal(false)} />
                    <section data-testid="settings-modal" className="fixed right-12 top-20 z-[149] w-[28rem] rounded-xl border border-white/10 bg-slate-950 p-3 space-y-2">
                        <div className="flex gap-1">
                            {['general', 'device', 'profiles', 'proof'].map((tab) => (
                                <button key={tab} data-testid={`settings-${tab}-tab`} type="button" onClick={() => setSettingsTab(tab)} className={`px-2 py-1 rounded border text-[9px] ${settingsTab === tab ? 'border-cyan-300/40 bg-cyan-500/10' : 'border-white/10'}`}>{tab}</button>
                            ))}
                        </div>
                        {settingsTab === 'general' && (
                            <label className="text-[10px] font-mono flex items-center justify-between">
                                Start in Simulator Mode
                                <input type="checkbox" checked={settings.general.startInSimulatorMode} onChange={(e) => setSettings((prev) => ({ ...prev, general: { ...prev.general, startInSimulatorMode: e.target.checked } }))} />
                            </label>
                        )}
                        {settingsTab === 'device' && (
                            <div className="space-y-1">
                                <label className="text-[10px] font-mono flex items-center justify-between">
                                    Auto-scan on launch
                                    <input data-testid="setting-auto-scan" type="checkbox" checked={settings.device.autoScanOnLaunch} onChange={(e) => setSettings((prev) => ({ ...prev, device: { ...prev.device, autoScanOnLaunch: e.target.checked } }))} />
                                </label>
                                <input data-testid="setting-openrgb-host" value={settings.device.openRgbHost} onChange={(e) => setSettings((prev) => ({ ...prev, device: { ...prev.device, openRgbHost: e.target.value } }))} className="w-full rounded border border-white/10 bg-black/30 px-2 py-1 text-[10px]" />
                                <input data-testid="setting-openrgb-port" type="number" value={settings.device.openRgbPort} onChange={(e) => setSettings((prev) => ({ ...prev, device: { ...prev.device, openRgbPort: Number(e.target.value) } }))} className="w-full rounded border border-white/10 bg-black/30 px-2 py-1 text-[10px]" />
                            </div>
                        )}
                        {settingsTab === 'profiles' && (
                            <label className="text-[10px] font-mono flex items-center justify-between">
                                Auto-apply last profile
                                <input data-testid="setting-auto-apply-profile" type="checkbox" checked={settings.profiles.autoApplyLastProfile} onChange={(e) => setSettings((prev) => ({ ...prev, profiles: { ...prev.profiles, autoApplyLastProfile: e.target.checked } }))} />
                            </label>
                        )}
                        {settingsTab === 'proof' && (
                            <input data-testid="setting-proof-output-folder" value={settings.proof.proofOutputFolder} onChange={(e) => setSettings((prev) => ({ ...prev, proof: { ...prev.proof, proofOutputFolder: e.target.value } }))} className="w-full rounded border border-white/10 bg-black/30 px-2 py-1 text-[10px]" />
                        )}
                        <div className="flex gap-1">
                            <button data-testid="settings-save-button" type="button" onClick={() => { writeStorage(HARDWARE_CUSTOMIZATION_SETTINGS_STORAGE_KEY, settings); setShowSettingsModal(false); }}>Save</button>
                            <button data-testid="settings-reset-button" type="button" onClick={() => setSettings(defaultSettings())}>Reset</button>
                        </div>
                    </section>
                </>
            )}
        </>
    );
}

